  test('retry backoff sleeps attempt*2s between attempts (2s, 4s), never after the last', function () {
    var slept = [];
    var r = run({}, { failPuts: 1 }, { sleepMs: function (ms) { slept.push(ms); } });
    assert.equal(r.result.status, 'published');
