  test('emits the grep-able "leg tokens:" line like the sh step', function () {
    var lines = [];
    run({}, {}, { log: function (l) { lines.push(l); } });
    var leg = lines.filter(function (l) { return l.indexOf('leg tokens:') === 0; })[0];
