      'mid-log fa-tokens:{"input":200,"output":20,"cacheRead":7}\n' +
      'fa-tokens:\t{"input":1000,"output":70,"cacheRead":88}');
    assert.equal(sums.input, 1300);
    assert.equal(sums.output, 100);
    assert.equal(sums.cacheRead, 100);
