function resolveAnchorKey(anchor) {
    var a = String(anchor === null || anchor === undefined ? '' : anchor);
    if (a.indexOf('pr-') === 0) return a;
    if (a.indexOf('gh-') === 0) return 'issue-' + a.slice(3);
    return null;
