/** Publish target: asset / branch / path / attempts (fa defaults). */
function tokensTargetOf(opts, repo) {
    var asset = opts.asset || (repo.split('/')[1] || 'factory') + '-tokens.json';
    return {
        asset: asset,
        branch: opts.branch || tokenUsage.DEFAULT_DATA_BRANCH,
